use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Register the libcurl backend for HTTP requests made by libgit2."] # [doc = ""] # [doc = " This function takes one parameter, a `handle`, which is used to perform all"] # [doc = " future HTTP requests. The handle can be previously configured with"] # [doc = " information such as proxies, SSL information, etc."] # [doc = ""] # [doc = " This function is unsafe largely for the same reasons as"] # [doc = " `git2::transport::register`:"] # [doc = ""] # [doc = " * The function needs to be synchronized against all other creations of"] # [doc = "   transport (any API calls to libgit2)."] # [doc = " * The function will leak `handle` as once registered it is not currently"] # [doc = "   possible to unregister the backend."] # [doc = ""] # [doc = " This function may be called concurrently, but only the first `handle` will"] # [doc = " be used. All others will be discarded."] pub unsafe fn register (handle : Easy) { static INIT : Once = Once :: new () ; let handle = Arc :: new (Mutex :: new (handle)) ; let handle2 = handle . clone () ; INIT . call_once (move | | { git2 :: transport :: register ("http" , move | remote | factory (remote , handle . clone ())) . unwrap () ; git2 :: transport :: register ("https" , move | remote | factory (remote , handle2 . clone ())) . unwrap () ; }) ; }